import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是覆盖配置相对仓库根的位置。
const thresholdsPath = "inventory/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 thresholds.json 里配置了就用配置值；文件不存在、解析失败或该仓库
// 没配，都回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadWarehouseThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadWarehouseThresholds 读取仓库根下 thresholds.json 的覆盖配置。
//
// 从工作目录向上找到最近的含 go.mod 的目录作为仓库根，因此无论服务从仓库根
// 启动、还是 `go test` 在包目录下运行，都定位到同一个 inventory/thresholds.json。
// 文件不存在或内容不是合法的 JSON 对象时返回空配置，调用方因此回退到默认值。
//
// 有意不缓存：每次调用重新读取，配置的新增/删除即时生效，也让「文件不存在
// 回退默认值」可被单测直接观测。
func loadWarehouseThresholds() map[string]int {
	data, err := os.ReadFile(filepath.Join(repoRoot(), thresholdsPath))
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// repoRoot 从工作目录向上找到最近的含 go.mod 的目录；找不到返回空串。
func repoRoot() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

