// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPaths 是覆盖配置 thresholds.json 的候选位置。
// 文件随包放在 inventory/thresholds.json：从仓库根运行时命中前一个，
// 在包目录下运行时（例如 `go test`）命中后一个。
var thresholdsPaths = []string{
	"inventory/thresholds.json",
	"thresholds.json",
}

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 仓库在 thresholds.json 里配置了就用配置值；文件不存在、解析失败或该仓库
// 没配，都回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := warehouseThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// warehouseThresholds 读取 thresholds.json 的覆盖配置。
// 文件不存在或内容不是合法的 JSON 对象时返回空配置，调用方因此回退到默认值。
func warehouseThresholds() map[string]int {
	for _, path := range thresholdsPaths {
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		var thresholds map[string]int
		if err := json.Unmarshal(data, &thresholds); err != nil {
			return nil
		}
		return thresholds
	}
	return nil
}

